import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, uniform, texture, uv, mul, add, sin } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const tex = ctx.textureLoader.load(config.assets.imageUrl);
  tex.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with atlas region aspect ratio (512x320 = 1.6:1)
  const aspectRatio = 512 / 320;
  const geom = new THREE.PlaneGeometry(aspectRatio, 1);

  // Create material with TSL shader nodes
  const mat = new MeshBasicNodeMaterial();

  // Sample base texture
  const texColor = texture(tex, uv());

  // Engineered gradient effect (vertical, subtle)
  const gradIntensity = uniform(0.1);
  const vertGrad = add(1.0, mul(uv().y, gradIntensity));
  const gradColor = mul(texColor, vertGrad);

  // Subtle procedural grain
  const grainFreq = uniform(50.0);
  const grainStr = uniform(0.06);
  const grainNoise = mul(
    sin(add(mul(uv().x, grainFreq), mul(uv().y, grainFreq))),
    grainStr
  );

  // Composite: gradient texture + grain
  mat.colorNode = add(gradColor, grainNoise);
  mat.transparent = true;

  // Create mesh
  const mesh = new THREE.Mesh(geom, mat);

  // Apply scene transforms from config
  const pos = config.scenePosition || {};
  mesh.position.set(pos.x || 0, pos.y || 0, pos.z || 0);

  const rot = config.sceneRotation || {};
  mesh.rotation.set(rot.x || 0, rot.y || 0, rot.z || 0);

  const scale = config.sceneScale || {};
  mesh.scale.set(scale.x || 1, scale.y || 1, scale.z || 1);

  // Apply cinematic primitives if specified
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    config.cinematicPrimitives.forEach(prim => {
      if (ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
        ctx.primitives[prim.name](mesh, prim.params || {});
      }
    });
  }

  group.add(mesh);

  // Setup event handlers
  group.userData.handlers = {};

  // Cleanup function for resource disposal
  group.userData.cleanup = function() {
    geom.dispose();
    mat.dispose();
    tex.dispose();
  };

  return group;
}
